class Solution:
    def countArrays(self, original, bounds):
        lo, hi = float('-inf'), float('inf')
        for o, (u, v) in zip(original, bounds):
            lo = max(lo, u - o)
            hi = min(hi, v - o)
        return max(0, hi - lo + 1)

