class Solution {
public:
    int countArrays(vector<int>& original, vector<vector<int>>& bounds) {
        int n = original.size();
        vector<long long> cands;
        for (int i = 0; i < n; i++) {
            cands.push_back((long long)bounds[i][0] - original[i]);
            cands.push_back((long long)bounds[i][1] - original[i]);
        }
        sort(cands.begin(), cands.end());
        cands.erase(unique(cands.begin(), cands.end()), cands.end());
        int ans = 0;
        for (long long d : cands) {
            bool ok = true;
            for (int i = 0; i < n && ok; i++)
                ok = bounds[i][0] <= original[i] + d && original[i] + d <= bounds[i][1];
            ans += ok;
        }
        return ans;
    }
};

