class Solution {
    public int countArrays(int[] original, int[][] bounds) {
        int n = original.length;
        java.util.Set<Long> set = new java.util.HashSet<>();
        for (int i = 0; i < n; i++) { set.add((long) bounds[i][0] - original[i]); set.add((long) bounds[i][1] - original[i]); }
        int ans = 0;
        for (long d : set) {
            boolean ok = true;
            for (int i = 0; i < n && ok; i++)
                ok = bounds[i][0] <= original[i] + d && original[i] + d <= bounds[i][1];
            if (ok) ans++;
        }
        return ans;
    }
}

